    input [31:0] s_axi_wdata,
    input [11:0] addra,
    input web,
    output reg done,
    output reg busy
);parameter RAM_DEPTH = 1024;
    parameter RAM_WIDTH = 32;

    reg [RAM_WIDTH-1:0] ram [0:RAM_DEPTH-1];
    reg [11:0] write_addr;
    reg [31:0] write_data;
