	clk,
	in,
	curr_out,
	read_out,
	we,
	bank,
	ureg,
	CRY,
	setCRY
);input reset, clk, we, bank, CRY, setCRY, ureg;
input [7:0] in;
output [7:0] curr_out, read_out;

reg [7:0] uCR, sCR;

assign curr_out = (bank == 0) ? uCR : sCR;

assign read_out = (ureg) ? uCR :
									(bank == 0) ? uCR : sCR;

