	if (reset) begin
		uCR <= 8'h8;
		sCR <= 8'h1;
	end else if (we) begin
		if (bank == 0 || ureg)
			uCR <= in;
		else
			sCR <= in;
	end else if (setCRY) begin
		if (bank == 0)
			uCR[1] <= CRY;
		else
			sCR[1] <= CRY;
	end
end


endmodule

