description:
Design a clock generator that produces a modulated output clock signal (clk_out) based on an input clock signal (clk_in). This module generates a clock signal with a defined period (10 time units) and a duty cycle of 25%. It counts cycles to determine when to output a HIGH signal (for 2.5 time units) followed by a LOW for the remainder of the period, repeating this process until a set cycle count (1024) is reached when clk_out goes LOW and stays LOW.
module top_module(
    input wire clk_in,
    output reg clk_out
);

code:
module top_module(
    input wire clk_in,
    output reg clk_out
);localparam CYCLE_COUNT = 1024;
localparam CLK_PERIOD = 10;
localparam CLK_DUTY_CYCLE = 0.25;
localparam CLK_SUB_PERIOD = CLK_PERIOD / 4;

reg [1:0] sub_clk_count;
reg [9:0] cycle_count;

always @(posedge clk_in) begin
    sub_clk_count <= sub_clk_count + 1;
    if (sub_clk_count == 2'b11) begin
        sub_clk_count <= 0;
        cycle_count <= cycle_count + 1;
    end
end

always @(posedge clk_in) begin
    if (cycle_count >= CYCLE_COUNT) begin
        clk_out <= 1'b0;
    end else begin
        if (sub_clk_count == 2'b00) begin
            clk_out <= 1'b1;
        end else if (sub_clk_count == 2'b01) begin
            clk_out <= 1'b0;
        end else if (sub_clk_count == 2'b10) begin
            clk_out <= 1'b0;
        end else if (sub_clk_count == 2'b11) begin
            clk_out <= 1'b0;
        end
    end
end

endmodule

