input sel,
output reg [15:0] out
);reg [7:0] sel_in1, sel_in2, sel_in3, sel_in4;

always @(*) begin
    sel_in1 = {in1, in2};
    sel_in2 = {in3, in4};
    sel_in3 = {in5, in6};
    sel_in4 = {in7, in8};
    case(sel)
        1'b0: begin
            case(choose)
                3'b000: out = {sel_in1};
                3'b001: out = {sel_in1[15:8], sel_in1[7:0]};
                3'b010: out = {sel_in2};
