                3'b100: out = {sel_in3};
                3'b101: out = {sel_in3[15:8], sel_in3[7:0]};
                3'b110: out = {sel_in4};
                3'b111: out = {sel_in4[15:8], sel_in4[7:0]};
                default: out = 16'b0;
            endcase
        end
        1'b1: begin
            case(choose)
                3'b000: out = {in1, in2};
                3'b001: out = {in1, in2[7:0], in3};
