description:
Design a state machine for controlling a vehicle's tail light system. The module transitions between various states based on the inputs for left and right turn signals, managing the output signals for left (LA, LB, LC) and right (RA, RB, RC) tail lights. When only the left turn signal is active, it sequentially illuminates the left lights from L1 to L3. Similarly, when only the right turn signal is engaged, it follows a sequence from R1 to R3. If both turn signals are activated, the system resets to an idle state, ensuring safety by preventing simultaneous left and right signaling. The clock and reset inputs synchronize the state transitions.
module top_module(
	input reset, left, right, clk,
	output LC, LB, LA, RA, RB, RC
);

code:
module top_module(
	input reset, left, right, clk,
	output LC, LB, LA, RA, RB, RC
);parameter ST_IDLE = 3'b000;
parameter ST_L1 = 3'b001;
parameter ST_L2 = 3'b010;
parameter ST_L3 = 3'b011;
parameter ST_R1 = 3'b100;
parameter ST_R2 = 3'b101;
parameter ST_R3 = 3'b110;

reg [2:0] state, next_state;

always @(posedge clk)
	if (reset)
		state <= ST_IDLE;
	else
		state <= next_state;

always @*
begin
	case (state)
		ST_IDLE: begin
			if (left && ~right)
				next_state = ST_L1;
			else if (~left && right)
				next_state = ST_R1;
			else
				next_state = ST_IDLE;
		end
		ST_L1: next_state = ST_L2;
		ST_L2: next_state = ST_L3;
		ST_R1: next_state = ST_R2;
		ST_R2: next_state = ST_R3;
		default: next_state = ST_IDLE;
	endcase
	if (left && right)
		next_state = ST_IDLE;

end

assign LA = state == ST_L1 || state == ST_L2 || state == ST_L3;
assign LB = state == ST_L2 || state == ST_L3;
assign LC = state == ST_L3;
assign RA = state == ST_R1 || state == ST_R2 || state == ST_R3;
assign RB = state == ST_R2 || state == ST_R3;
assign RC = state == ST_R3;

endmodule

