description:
Implement the Verilog module based on the following description.
Build a 4-bit binary up-counter with synchronous active high reset signal.
// (1) reset: Resets the counter to 4'b0000.
// (2) q: The value of the counter.

module top_module(
    input clk,
    input reset,
    output reg [3:0] q);

code:
module top_module(
    input clk,
    input reset,
    output reg [3:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the counter to 4'b0000
            q <= 4'b0000;
        end else begin
            // Binary up-counter: Increment the counter
            q <= q + 1;
        end
    end

endmodule

