description:
Design a 4-bit binary counter that increments its count on each positive clock edge. When the reset input is low, the counter resets to zero; otherwise, it continues counting upwards from its current value. The current count is outputted as a 4-bit signal.
module top_module(
   clk,
   reset,
   count_out
);

code:
module top_module(
   clk,
   reset,
   count_out
);input            clk;
    input            reset;
    output  [3:0]    count_out;

    reg  [3:0]        count_out_reg;

    always @(posedge clk or negedge reset) begin
        if (~reset) begin
            count_out_reg <= 4'b0000;
        end
        else begin
            count_out_reg <= count_out_reg + 1;
        end
    end

    assign count_out = count_out_reg;

endmodule

